use std::collections::BTreeSet;
use std::fs;
use std::path::Path;
use std::process::Command;

use eros::Context as _;

use crate::cmd;

const SRC: &str = "crates/odyssey-autocalib/src";
const OUT: &str = "orbbec/ffi.rs";
/// The backend files whose SDK mentions decide what is emitted.
const SOURCES: [&str; 2] = ["orbbec.rs", "orbbec/runtime.rs"];
const HEADER: &str = "libobsensor/ObSensor.h";

const RAW_LINES: [&str; 5] = [
    "// Function table for the OrbbecSDK v2 C API, version 2.10.6.",
    "//",
    "// Generated by `cargo xtask autocalib orbbec-ffi` with bindgen 0.72.1. Do not edit;",
    "// change crates/xtask/src/autocalib/orbbec_ffi.rs or the backend sources and run it again.",
    r#"#![expect(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, clippy::undocumented_unsafe_blocks, clippy::multiple_unsafe_ops_per_block, reason = "bindgen output: C names, the full enum tables, and unsafe wrappers whose contract is that of the C function")]"#,
];

#[derive(Clone, Copy)]
enum Start {
    /// The match must begin at a word boundary, like grep's `\b`.
    WordBoundary,
    Anywhere,
}

fn is_word(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_'
}

fn is_lower_ident(byte: u8) -> bool {
    byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_'
}

/// Every non-overlapping `<prefix><tail>+` in `text`, as `grep -o` finds it, with
/// `strip` cut off the front of each match.
fn matches(
    text: &str,
    prefix: &str,
    tail: fn(u8) -> bool,
    start: Start,
    strip: &str,
    found: &mut BTreeSet<String>,
) {
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let at_start = match start {
            Start::WordBoundary => i == 0 || !is_word(bytes[i - 1]),
            Start::Anywhere => true,
        };
        if at_start && bytes[i..].starts_with(prefix.as_bytes()) {
            let mut end = i + prefix.len();
            while end < bytes.len() && tail(bytes[end]) {
                end += 1;
            }
            if end > i + prefix.len() {
                found.insert(text[i + strip.len()..end].to_owned());
                i = end;
                continue;
            }
        }
        i += 1;
    }
}

struct Mentions {
    /// `\bob_[a-z0-9_]+`
    functions: BTreeSet<String>,
    /// `ffi::OB[A-Za-z0-9_]+` without the `ffi::`
    constants: BTreeSet<String>,
    /// `ffi::ob_[a-z0-9_]+` without the `ffi::`
    types: BTreeSet<String>,
}

fn mentions(texts: &[String]) -> Mentions {
    let mut found = Mentions {
        functions: BTreeSet::new(),
        constants: BTreeSet::new(),
        types: BTreeSet::new(),
    };
    for text in texts {
        let functions = &mut found.functions;
        matches(
            text,
            "ob_",
            is_lower_ident,
            Start::WordBoundary,
            "",
            functions,
        );
        let constants = &mut found.constants;
        matches(
            text,
            "ffi::OB",
            is_word,
            Start::Anywhere,
            "ffi::",
            constants,
        );
        matches(
            text,
            "ffi::ob_",
            is_lower_ident,
            Start::Anywhere,
            "ffi::",
            &mut found.types,
        );
    }
    found
}

fn anchored(names: &BTreeSet<String>) -> String {
    let alternatives: Vec<&str> = names.iter().map(String::as_str).collect();
    format!("^({})$", alternatives.join("|"))
}

/// The name declared by a `pub const OB<ident>:` line: its third whitespace field
/// minus the colon.
fn sdk_constant(line: &str) -> Option<&str> {
    let ident = line.strip_prefix("pub const OB")?;
    let len = ident.bytes().take_while(|&byte| is_word(byte)).count();
    if len == 0 || ident.as_bytes().get(len) != Some(&b':') {
        return None;
    }
    let field = line.split_whitespace().nth(2)?;
    Some(field.strip_suffix(':').unwrap_or(field))
}

/// Drops the `OB*` constants not in `keep` and narrows visibility: the function
/// table is private to the backend, so declarations and methods become
/// `pub(super)` while generated fields stay public for access through Sdk.
fn filter(generated: &str, keep: &BTreeSet<String>) -> String {
    let mut out = String::new();
    let mut skipping = false;
    for line in generated.lines() {
        if skipping {
            skipping = !line.ends_with(';');
            continue;
        }
        if let Some(name) = sdk_constant(line)
            && !keep.contains(name)
        {
            // rustfmt wraps long constants onto a second line.
            skipping = !line.ends_with(';');
            continue;
        }
        let line = if let Some(rest) = line.strip_prefix("pub ") {
            format!("pub(super) {rest}")
        } else if let Some(rest) = line.strip_prefix("    pub unsafe fn ") {
            format!("    pub(super) unsafe fn {rest}")
        } else {
            line.to_owned()
        };
        out.push_str(&line.replace("Ok(OrbbecSdk {", "Ok(Self {"));
        out.push('\n');
    }
    out
}

pub(super) fn regenerate(include: &Path) -> eros::Result<()> {
    eros::ensure!(
        include.join(HEADER).is_file(),
        "{} is not an OrbbecSDK v2.10.6 include dir containing {HEADER}",
        include.display()
    );
    let include = std::path::absolute(include).context("resolving the include dir")?;
    let src = cmd::root().join(SRC);
    let out = src.join(OUT);
    let mut texts = Vec::new();
    for source in SOURCES {
        let path = src.join(source);
        texts.push(
            fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?,
        );
    }
    let found = mentions(&texts);

    let tmp = std::env::temp_dir().join(format!("orbbec-ffi-{}.rs", std::process::id()));
    let mut bindgen = Command::new("bindgen");
    bindgen
        .arg(include.join(HEADER))
        .arg("--output")
        .arg(&tmp)
        .args([
            "--formatter",
            "rustfmt",
            "--no-layout-tests",
            "--no-doc-comments",
        ])
        .args([
            "--dynamic-loading",
            "OrbbecSdk",
            "--dynamic-link-require-all",
        ])
        .args(["--allowlist-function", &anchored(&found.functions)])
        .args(["--allowlist-type", &anchored(&found.types)]);
    for line in RAW_LINES {
        bindgen.args(["--raw-line", line]);
    }
    bindgen.arg("--").arg(format!("-I{}", include.display()));
    let generated = cmd::run(&mut bindgen).and_then(|()| {
        Ok(fs::read_to_string(&tmp).with_context(|| format!("reading {}", tmp.display()))?)
    });
    // Best effort: a leftover temp file is harmless.
    let _ = fs::remove_file(&tmp);

    fs::write(&out, filter(&generated?, &found.constants))
        .with_context(|| format!("writing {}", out.display()))?;
    cmd::run(Command::new("rustfmt").arg(&out))?;
    println!("wrote {}", out.display());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn set(names: &[&str]) -> BTreeSet<String> {
        names.iter().map(|name| (*name).to_owned()).collect()
    }

    #[test]
    fn finds_mentions_like_grep() {
        let text = "let p = unsafe { (sdk.ob_create_pipeline)(&mut e) };\n\
                    xob_not_this(); ob_ ; ob_fooBar ffi::OB_FORMAT_RGB as ffi::ob_format;\n\
                    myffi::OBX ffi::OB ffi::ob_";
        let found = mentions(&[text.to_owned()]);
        assert_eq!(
            found.functions,
            set(&["ob_create_pipeline", "ob_foo", "ob_format"])
        );
        assert_eq!(found.constants, set(&["OBX", "OB_FORMAT_RGB"]));
        assert_eq!(found.types, set(&["ob_format"]));
    }

    #[test]
    fn anchored_alternation() {
        assert_eq!(anchored(&set(&["ob_b", "ob_a"])), "^(ob_a|ob_b)$");
        assert_eq!(anchored(&set(&[])), "^()$");
    }

    #[test]
    fn filter_drops_unused_constants_and_narrows_visibility() {
        let generated = "pub const OB_KEEP: u32 = 1;\n\
                         pub const OB_DROP: u32 = 2;\n\
                         pub const OB_DROP_WRAPPED: ob_format =\n    \
                             ob_format_OB_FORMAT_YUYV;\n\
                         pub const OTHER: u32 = 3;\n\
                         pub struct OrbbecSdk {\n\
                         \x20   pub ob_x: fn(),\n\
                         }\n\
                         \x20   pub unsafe fn ob_x(&self) {}\n\
                         \x20   Ok(OrbbecSdk { ob_x })\n";
        let expected = "pub(super) const OB_KEEP: u32 = 1;\n\
                        pub(super) const OTHER: u32 = 3;\n\
                        pub(super) struct OrbbecSdk {\n\
                        \x20   pub ob_x: fn(),\n\
                        }\n\
                        \x20   pub(super) unsafe fn ob_x(&self) {}\n\
                        \x20   Ok(Self { ob_x })\n";
        assert_eq!(filter(generated, &set(&["OB_KEEP"])), expected);
    }

    #[test]
    fn sdk_constant_needs_colon_after_name() {
        assert_eq!(sdk_constant("pub const OB_A: u32 = 1;"), Some("OB_A"));
        assert_eq!(sdk_constant("pub const OB: u32 = 1;"), None);
        assert_eq!(sdk_constant("pub const OB_A = 1;"), None);
        assert_eq!(sdk_constant("pub const OB_A:u32 = 1;"), Some("OB_A:u32"));
    }
}
